/* ========== 装饰贴图 ========== */
/* 我方气泡 - 右上角装饰 */
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;  /* 允许贴图超出气泡边界 */
}
.bubble-me-custom::after {
  content: "";
  position: absolute;
  /* ===== 可调整：贴图位置 ===== */
  top: 2px;        /* 向上偏移（负值越大约靠上） */
  right: -2px;   /* 向右偏移（负值越大约靠右） */
  /* ===== 可调整：贴图大小 ===== */
  width: 10px;     /* 宽度 */
  height: 10px;    /* 高度 */
