  pointer-events: none;  /* 让贴图不干扰点击 */
  z-index: 2;
}
/* 对方气泡 - 左上角装饰 */
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;  /* 允许贴图超出气泡边界 */
}
.bubble-them-custom::before {
  content: "";
  position: absolute;
