.input-btn-ai { width: var(--ai-btn-size) !important; height: var(--ai-btn-size) !important; min-width: var(--ai-btn-size) !important; min-height: var(--ai-btn-size) !important; max-width: var(--ai-btn-size) !important; max-height: var(--ai-btn-size) !important; background-image: url('https://img.heliar.top/file/1780293958180_IMG_5443.png') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; background-color: transparent !important; flex-shrink: 0 !important; margin-left: var(--ai-btn-margin-left, 8px) !important; padding: 0 !important; }
.input-box-custom, .input-box-custom textarea, .input-box-custom input, .input-box-custom div[contenteditable="true"] { color: #1a1a1a !important; -webkit-text-fill-color: #1a1a1a !important; caret-color: #1a1a1a !important; }

/* --- 引用消息与回复 --- */
.chat-detail-screen { --reply-bar-accent: transparent; --reply-bar-bg: #ffffff; --reply-bar-padding: 8px 12px; --reply-bar-margin-bottom: 0px; --reply-bar-name-size: 12px; --reply-bar-text-color: rgba(255,255,255,0.5); --reply-bar-text-size: 12px; --reply-bar-content-padding-left: 10px; }
