.msg-reply-detached-them::before { content: '' !important; position: absolute !important; left: -8px !important; top: 50% !important; transform: translateY(-50%) !important; width: 3px !important; height: 70% !important; background: #d4d4d4 !important; border-radius: 999px !important; pointer-events: none !important; }

/* --- 翻译 --- */
.msg-translation-btn {
   margin-top: -24px;
   opacity: 0;
}
.msg-translation-wrapper {
   margin-top: -7px;
}
.msg-translation-content {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 3px 0 1px 0 !important;
  text-align: left !important;
}
.msg-translation-content::before {
  content: '' !important;
  display: block !important;
  width: 100% !important;
  border-top: 1px solid rgba(255, 255, 255, 0.3) !important;
