}

/* --- 不显示小尾巴的消息类型 --- */
/* 表情包、转账、礼物、图片、语音、视频通话、游戏卡、问卷、论坛分享、
   合并转发、情侣邀请、群邀请卡、朋友圈转发 — 一律不要外层贴图 */
.bubble-me-custom.msg-sticker::before,  .bubble-me-custom.msg-sticker::after,
.bubble-them-custom.msg-sticker::before, .bubble-them-custom.msg-sticker::after,

.bubble-me-custom:has(.msg-transfer-card)::before,
.bubble-me-custom:has(.msg-transfer-card)::after,
.bubble-them-custom:has(.msg-transfer-card)::before,
.bubble-them-custom:has(.msg-transfer-card)::after,

.bubble-me-custom:has(.msg-gift-card)::before,
.bubble-me-custom:has(.msg-gift-card)::after,
.bubble-them-custom:has(.msg-gift-card)::before,
.bubble-them-custom:has(.msg-gift-card)::after,

.bubble-me-custom:has(img)::before,   /* 图片消息 */
.bubble-me-custom:has(img)::after,
.bubble-them-custom:has(img)::before,
.bubble-them-custom:has(img)::after,

.bubble-me-custom:has(.msg-voice)::before,
.bubble-me-custom:has(.msg-voice)::after,
.bubble-them-custom:has(.msg-voice)::before,
.bubble-them-custom:has(.msg-voice)::after,

.bubble-me-custom:has(.msg-videocall-log)::before,
.bubble-me-custom:has(.msg-videocall-log)::after,
.bubble-them-custom:has(.msg-videocall-log)::before,
.bubble-them-custom:has(.msg-videocall-log)::after,

.bubble-me-custom:has(.msg-forum-share)::before,
.bubble-me-custom:has(.msg-forum-share)::after,
.bubble-them-custom:has(.msg-forum-share)::before,
.bubble-them-custom:has(.msg-forum-share)::after,

/* 通用兜底：no-padding 的统统是卡片型，不要贴图 */
